import heapq

class Solution:
    def maxTransactions(self, amounts: list[int]) -> int:
        running_sum = 0
        min_heap = [] # stores negative transactions taken
        count = 0
        for x in amounts:
            if x >= 0:
                running_sum += x
                count += 1
            else:
                running_sum += x
                count += 1
                heapq.heappush(min_heap, x)
                if running_sum < 0:
                    # Pop the most negative transaction to restore feasibility
                    worst = heapq.heappop(min_heap)
                    running_sum -= worst
                    count -= 1
        return count

#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    int maxTransactions(vector<int>& amounts) {
        long long running_sum = 0;
        priority_queue<int, vector<int>, greater<int>> min_heap; // stores negative values
        int count = 0;
        for (int x : amounts) {
            running_sum += x;
            count++;
            if (x < 0) {
                min_heap.push(x);
                if (running_sum < 0) {
                    int worst = min_heap.top();
                    min_heap.pop();
                    running_sum -= worst;
                    count--;
                }
            }
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int maxTransactions(int[] amounts) {
        long runningSum = 0;
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        int count = 0;
        for (int x : amounts) {
            runningSum += x;
            count++;
            if (x < 0) {
                minHeap.offer(x);
                if (runningSum < 0) {
                    int worst = minHeap.poll();
                    runningSum -= worst;
                    count--;
                }
            }
        }
        return count;
    }
}

var maxTransactions = function(amounts) {
    let runningSum = 0;
    const negs = [];
    let count = 0;
    for (const x of amounts) {
        runningSum += x;
        count++;
        if (x < 0) {
            negs.push(x);
            negs.sort((a, b) => a - b);
            if (runningSum < 0) {
                const worst = negs.shift();
                runningSum -= worst;
                count--;
            }
        }
    }
    return count;
};
